// @author: Greg Paskal
// @company: MissionWares
//
// @description:
// Data model representing a single recommendation generated by the mAi Advisor™.
// Each recommendation is tailored to a specific audience and contains either
// Understanding tier (what's wrong and why it matters) or Action tier (detailed
// steps, code examples, and verification procedures). Recommendations are generated
// from audit findings and template content, customized based on detected framework
// and audience responsibilities. Supports both rule-based and AI-enhanced content.
//
// @two-tier-model:
// - Tier 1 (UNDERSTANDING): Summary, impact, business context, priority
//   Available to: ALL audiences
// - Tier 2 (ACTION): Steps, code, tests, verification, effort estimates
//   Available to: Implementers only (DEVELOPER, OPS, QA)
//
// @dependencies:
// - framework.advisor.FW_AdvisorAudience
// - java.time.LocalDateTime
// - java.util.List
//
// @tags: advisor, mAi™, recommendation, guidance, data-model, output
//
// @changeLog:
// Date        Author          Version  Description
// ----------  --------------  -------  --------------------------
// 2025-10-07  G. Paskal       1.0.0    Initial creation - recommendation model
// ===============================================================

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/**
 * Recommendation data model for mAi Advisor™ guidance.
 * 
 * <p>Represents a single, audience-specific recommendation generated from
 * an audit finding. Each recommendation is tailored to the target audience's
 * role and expertise level, providing either understanding-level context
 * or actionable implementation guidance.
 * 
 * <p><b>Two-Tier Model:</b>
 * <ul>
 *   <li><b>UNDERSTANDING Tier:</b> What's wrong, why it matters, business impact.
 *       All audiences receive this tier.</li>
 *   <li><b>ACTION Tier:</b> How to fix it, code examples, verification steps.
 *       Only implementers receive this tier.</li>
 * </ul>
 * 
 * <p><b>Usage Example:</b>
 * <pre>
 * FW_AdvisorRecommendation rec = new FW_AdvisorRecommendation()
 *     .setFindingType("HSTS_MISSING")
 *     .setSeverity("HIGH")
 *     .setTargetAudience(FW_AdvisorAudience.DEVELOPER)
 *     .setTier(RecommendationTier.ACTION)
 *     .setSummary("HTTPS Strict Transport Security header is missing")
 *     .setImpact("Users vulnerable to protocol downgrade attacks")
 *     .setCodeExample("response.setHeader('Strict-Transport-Security', '...')");
 * </pre>
 * 
 * @since 1.0.0
 * @see framework.advisor.FW_AdvisorAudience
 * @see framework.advisor.FW_AdvisorEngine
 */
public class FW_AdvisorRecommendation {
    
    /**
     * Recommendation tier enumeration.
     * Defines whether a recommendation provides understanding or action guidance.
     */
    public enum RecommendationTier {
        /** Understanding tier - explains what and why (all audiences) */
        UNDERSTANDING,
        /** Action tier - explains how to fix (implementers only) */
        ACTION
    }
    
    /**
     * Severity level enumeration for recommendations.
     * Maps to audit finding severity levels.
     */
    public enum Severity {
        CRITICAL,
        HIGH,
        MEDIUM,
        LOW,
        INFO
    }
    
    // ===== FINDING IDENTIFICATION =====
    
    /** Unique finding identifier (e.g., "SEC-001") */
    private String findingId;
    
    /** Finding type constant (e.g., "HSTS_MISSING") */
    private String findingType;
    
    /** Finding category (SECURITY, PERFORMANCE, COMPLIANCE, INFRASTRUCTURE) */
    private String category;
    
    /** Severity level of the finding */
    private Severity severity;
    
    // ===== AUDIENCE & TIER =====
    
    /** Target audience for this recommendation */
    private FW_AdvisorAudience targetAudience;
    
    /** Recommendation tier (UNDERSTANDING or ACTION) */
    private RecommendationTier tier;
    
    // ===== TIER 1: UNDERSTANDING CONTENT (All Audiences) =====
    
    /** Brief summary of the finding (1-2 sentences) */
    private String summary;
    
    /** Impact explanation relevant to target audience */
    private String impact;
    
    /** Business context and consequences */
    private String businessContext;
    
    /** Priority level for this audience (HIGH/MEDIUM/LOW) */
    private String priority;
    
    /** List of CVE references related to this finding */
    private List<String> cveReferences;
    
    // ===== TIER 2: ACTION CONTENT (Implementers Only) =====
    
    /** Step-by-step action instructions */
    private String actionSteps;
    
    /** Code example (framework-specific when possible) */
    private String codeExample;
    
    /** Testing and validation guidance */
    private String testingGuidance;
    
    /** Verification steps to confirm fix works */
    private String verificationSteps;
    
    /** Effort estimate (e.g., "2-3 hours") */
    private String effortEstimate;
    
    /** Sprint points estimate (if applicable) */
    private Integer sprintPoints;
    
    /** List of other audiences to coordinate with */
    private List<String> coordinateWith;
    
    /** List of reference resources (links, docs, tools) */
    private List<String> resources;
    
    /** Rollback plan (for infrastructure changes) */
    private String rollbackPlan;
    
    // ===== METADATA =====
    
    /** True if AI enhanced the recommendation content */
    private boolean aiEnhanced;
    
    /** AI provider used (if applicable) */
    private String aiProvider;
    
    /** Framework detected from audit data */
    private String frameworkDetected;
    
    /** Timestamp when recommendation was generated */
    private LocalDateTime generatedAt;
    
    /** Template version used to generate this recommendation */
    private String templateVersion;
    
    /** Additional notes or context */
    private String notes;
    
    // ===== CONSTRUCTORS =====
    
    /**
     * Default constructor.
     * Initializes lists and sets generation timestamp.
     */
    public FW_AdvisorRecommendation() {
        this.cveReferences = new ArrayList<>();
        this.coordinateWith = new ArrayList<>();
        this.resources = new ArrayList<>();
        this.generatedAt = LocalDateTime.now();
        this.aiEnhanced = false;
    }
    
    /**
     * Constructor with basic identification.
     * 
     * @param findingType Finding type constant
     * @param targetAudience Target audience for this recommendation
     * @param tier Recommendation tier
     */
    public FW_AdvisorRecommendation(
            String findingType,
            FW_AdvisorAudience targetAudience,
            RecommendationTier tier) {
        this();
        this.findingType = findingType;
        this.targetAudience = targetAudience;
        this.tier = tier;
    }
    
    // ===== GETTERS =====
    
    public String getFindingId() { return findingId; }
    public String getFindingType() { return findingType; }
    public String getCategory() { return category; }
    public Severity getSeverity() { return severity; }
    public FW_AdvisorAudience getTargetAudience() { return targetAudience; }
    public RecommendationTier getTier() { return tier; }
    public String getSummary() { return summary; }
    public String getImpact() { return impact; }
    public String getBusinessContext() { return businessContext; }
    public String getPriority() { return priority; }
    public List<String> getCveReferences() { return cveReferences; }
    public String getActionSteps() { return actionSteps; }
    public String getCodeExample() { return codeExample; }
    public String getTestingGuidance() { return testingGuidance; }
    public String getVerificationSteps() { return verificationSteps; }
    public String getEffortEstimate() { return effortEstimate; }
    public Integer getSprintPoints() { return sprintPoints; }
    public List<String> getCoordinateWith() { return coordinateWith; }
    public List<String> getResources() { return resources; }
    public String getRollbackPlan() { return rollbackPlan; }
    public boolean isAiEnhanced() { return aiEnhanced; }
    public String getAiProvider() { return aiProvider; }
    public String getFrameworkDetected() { return frameworkDetected; }
    public LocalDateTime getGeneratedAt() { return generatedAt; }
    public String getTemplateVersion() { return templateVersion; }
    public String getNotes() { return notes; }
    
    // ===== SETTERS (Fluent API) =====
    
    public FW_AdvisorRecommendation setFindingId(String findingId) {
        this.findingId = findingId;
        return this;
    }
    
    public FW_AdvisorRecommendation setFindingType(String findingType) {
        this.findingType = findingType;
        return this;
    }
    
    public FW_AdvisorRecommendation setCategory(String category) {
        this.category = category;
        return this;
    }
    
    public FW_AdvisorRecommendation setSeverity(Severity severity) {
        this.severity = severity;
        return this;
    }
    
    public FW_AdvisorRecommendation setSeverity(String severity) {
        try {
            this.severity = Severity.valueOf(severity.toUpperCase());
        } catch (IllegalArgumentException e) {
            this.severity = Severity.MEDIUM; // Default fallback
        }
        return this;
    }
    
    public FW_AdvisorRecommendation setTargetAudience(FW_AdvisorAudience targetAudience) {
        this.targetAudience = targetAudience;
        return this;
    }
    
    public FW_AdvisorRecommendation setTier(RecommendationTier tier) {
        this.tier = tier;
        return this;
    }
    
    public FW_AdvisorRecommendation setSummary(String summary) {
        this.summary = summary;
        return this;
    }
    
    public FW_AdvisorRecommendation setImpact(String impact) {
        this.impact = impact;
        return this;
    }
    
    public FW_AdvisorRecommendation setBusinessContext(String businessContext) {
        this.businessContext = businessContext;
        return this;
    }
    
    public FW_AdvisorRecommendation setPriority(String priority) {
        this.priority = priority;
        return this;
    }
    
    public FW_AdvisorRecommendation setCveReferences(List<String> cveReferences) {
        this.cveReferences = cveReferences;
        return this;
    }
    
    public FW_AdvisorRecommendation addCveReference(String cveReference) {
        if (this.cveReferences == null) {
            this.cveReferences = new ArrayList<>();
        }
        this.cveReferences.add(cveReference);
        return this;
    }
    
    public FW_AdvisorRecommendation setActionSteps(String actionSteps) {
        this.actionSteps = actionSteps;
        return this;
    }
    
    public FW_AdvisorRecommendation setCodeExample(String codeExample) {
        this.codeExample = codeExample;
        return this;
    }
    
    public FW_AdvisorRecommendation setTestingGuidance(String testingGuidance) {
        this.testingGuidance = testingGuidance;
        return this;
    }
    
    public FW_AdvisorRecommendation setVerificationSteps(String verificationSteps) {
        this.verificationSteps = verificationSteps;
        return this;
    }
    
    public FW_AdvisorRecommendation setEffortEstimate(String effortEstimate) {
        this.effortEstimate = effortEstimate;
        return this;
    }
    
    public FW_AdvisorRecommendation setSprintPoints(Integer sprintPoints) {
        this.sprintPoints = sprintPoints;
        return this;
    }
    
    public FW_AdvisorRecommendation setCoordinateWith(List<String> coordinateWith) {
        this.coordinateWith = coordinateWith;
        return this;
    }
    
    public FW_AdvisorRecommendation addCoordinateWith(String audience) {
        if (this.coordinateWith == null) {
            this.coordinateWith = new ArrayList<>();
        }
        this.coordinateWith.add(audience);
        return this;
    }
    
    public FW_AdvisorRecommendation setResources(List<String> resources) {
        this.resources = resources;
        return this;
    }
    
    public FW_AdvisorRecommendation addResource(String resource) {
        if (this.resources == null) {
            this.resources = new ArrayList<>();
        }
        this.resources.add(resource);
        return this;
    }
    
    public FW_AdvisorRecommendation setRollbackPlan(String rollbackPlan) {
        this.rollbackPlan = rollbackPlan;
        return this;
    }
    
    public FW_AdvisorRecommendation setAiEnhanced(boolean aiEnhanced) {
        this.aiEnhanced = aiEnhanced;
        return this;
    }
    
    public FW_AdvisorRecommendation setAiProvider(String aiProvider) {
        this.aiProvider = aiProvider;
        return this;
    }
    
    public FW_AdvisorRecommendation setFrameworkDetected(String frameworkDetected) {
        this.frameworkDetected = frameworkDetected;
        return this;
    }
    
    public FW_AdvisorRecommendation setGeneratedAt(LocalDateTime generatedAt) {
        this.generatedAt = generatedAt;
        return this;
    }
    
    public FW_AdvisorRecommendation setTemplateVersion(String templateVersion) {
        this.templateVersion = templateVersion;
        return this;
    }
    
    public FW_AdvisorRecommendation setNotes(String notes) {
        this.notes = notes;
        return this;
    }
    
    // ===== HELPER METHODS =====
    
    /**
     * Checks if this recommendation contains action-level guidance.
     * 
     * @return true if tier is ACTION, false otherwise
     */
    public boolean isActionTier() {
        return tier == RecommendationTier.ACTION;
    }
    
    /**
     * Checks if this recommendation is understanding-level only.
     * 
     * @return true if tier is UNDERSTANDING, false otherwise
     */
    public boolean isUnderstandingTier() {
        return tier == RecommendationTier.UNDERSTANDING;
    }
    
    /**
     * Checks if this recommendation has code examples.
     * 
     * @return true if code example is not null and not empty
     */
    public boolean hasCodeExample() {
        return codeExample != null && !codeExample.trim().isEmpty();
    }
    
    /**
     * Checks if this recommendation has testing guidance.
     * 
     * @return true if testing guidance is not null and not empty
     */
    public boolean hasTestingGuidance() {
        return testingGuidance != null && !testingGuidance.trim().isEmpty();
    }
    
    /**
     * Checks if this recommendation requires coordination with other teams.
     * 
     * @return true if coordinateWith list is not empty
     */
    public boolean requiresCoordination() {
        return coordinateWith != null && !coordinateWith.isEmpty();
    }
    
    /**
     * Gets a formatted timestamp string.
     * 
     * @return Formatted timestamp in CDT (e.g., "2025-10-07 12:40:00 PM CDT")
     */
    public String getFormattedTimestamp() {
        if (generatedAt == null) {
            return "Unknown";
        }
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd hh:mm:ss a");
        return generatedAt.format(formatter) + " CDT";
    }
    
    /**
     * Gets the severity as a display string.
     * 
     * @return Severity level as string (e.g., "HIGH")
     */
    public String getSeverityString() {
        return severity != null ? severity.toString() : "UNKNOWN";
    }
    
    /**
     * Gets the tier as a display string.
     * 
     * @return Tier level as string (e.g., "ACTION")
     */
    public String getTierString() {
        return tier != null ? tier.toString() : "UNKNOWN";
    }
    
    /**
     * Validates that this recommendation has minimum required fields.
     * 
     * @return true if valid, false otherwise
     */
    public boolean isValid() {
        return findingType != null && !findingType.trim().isEmpty() &&
               targetAudience != null &&
               tier != null &&
               summary != null && !summary.trim().isEmpty();
    }
    
    /**
     * Gets a list of validation errors.
     * 
     * @return List of validation error messages (empty if valid)
     */
    public List<String> getValidationErrors() {
        List<String> errors = new ArrayList<>();
        
        if (findingType == null || findingType.trim().isEmpty()) {
            errors.add("Finding type is required");
        }
        if (targetAudience == null) {
            errors.add("Target audience is required");
        }
        if (tier == null) {
            errors.add("Recommendation tier is required");
        }
        if (summary == null || summary.trim().isEmpty()) {
            errors.add("Summary is required");
        }
        
        // Tier-specific validation
        if (tier == RecommendationTier.ACTION) {
            if (actionSteps == null || actionSteps.trim().isEmpty()) {
                errors.add("Action steps required for ACTION tier");
            }
        }
        
        return errors;
    }
    
    // ===== OVERRIDE METHODS =====
    
    /**
     * Returns a string representation of this recommendation.
     * 
     * @return String with finding type, audience, and tier
     */
    @Override
    public String toString() {
        return String.format(
            "FW_AdvisorRecommendation[%s | %s | %s | %s]",
            findingType != null ? findingType : "UNKNOWN",
            targetAudience != null ? targetAudience.getShortName() : "UNKNOWN",
            tier != null ? tier : "UNKNOWN",
            severity != null ? severity : "UNKNOWN"
        );
    }
    
    /**
     * Returns a detailed multi-line string representation.
     * Useful for debugging and logging.
     * 
     * @return Detailed string representation
     */
    public String toDetailedString() {
        StringBuilder sb = new StringBuilder();
        sb.append("=== mAi Advisor™ Recommendation ===\n");
        sb.append("Finding: ").append(findingType).append(" (").append(getSeverityString()).append(")\n");
        sb.append("Audience: ").append(targetAudience != null ? targetAudience.getDisplayName() : "Unknown").append("\n");
        sb.append("Tier: ").append(getTierString()).append("\n");
        sb.append("Summary: ").append(summary != null ? summary : "N/A").append("\n");
        
        if (isActionTier()) {
            sb.append("Has Code: ").append(hasCodeExample() ? "Yes" : "No").append("\n");
            sb.append("Has Tests: ").append(hasTestingGuidance() ? "Yes" : "No").append("\n");
            sb.append("Effort: ").append(effortEstimate != null ? effortEstimate : "N/A").append("\n");
        }
        
        sb.append("AI Enhanced: ").append(aiEnhanced ? "Yes" : "No").append("\n");
        sb.append("Framework: ").append(frameworkDetected != null ? frameworkDetected : "Auto-detect").append("\n");
        sb.append("Generated: ").append(getFormattedTimestamp()).append("\n");
        sb.append("Valid: ").append(isValid() ? "Yes" : "No");
        
        return sb.toString();
    }
}